<script setup lang="ts">
import {ref} from 'vue'
import {useStudio} from './studioContext'
const s=useStudio(),report=ref<any>(null),reviewed=ref(false),version=ref(0),error=ref(''),busy=ref(false)
async function inspect(){busy.value=true;error.value='';try{await s.saveAll();report.value=await s.api(`/projects/${s.p.value.id}/narrative/inspect`);version.value=report.value.projectVersion;reviewed.value=false}catch(e:any){error.value=e.message}finally{busy.value=false}}
function url(format:string,draft:boolean){return `/api/projects/${s.p.value.id}/narrative/export?format=${format}&draft=${draft}&reviewed=${reviewed.value}&version=${version.value}`}
async function download(format:string,draft:boolean){busy.value=true;error.value='';try{const response=await fetch(url(format,draft));if(!response.ok){const value=await response.json();throw Error(typeof value.detail==='string'?value.detail:value.detail?.message||'导出未完成，请重新检查')}const blob=await response.blob(),link=document.createElement('a'),objectUrl=URL.createObjectURL(blob);link.href=objectUrl;link.download=`narrative-${s.p.value.id}.${format}`;link.click();setTimeout(()=>URL.revokeObjectURL(objectUrl),10000)}catch(e:any){error.value=e.message}finally{busy.value=false}}
</script>
<template><section class="extension-panel"><h3>叙事包导出</h3><p class="muted">导出可用制作内容、知识绑定、解锁关系与可用素材。离线包不提供实时模型服务。</p><button :disabled="busy" @click="inspect">检查当前叙事包（不调用模型）</button><p v-if="error" class="extension-error">{{error}}</p><template v-if="report"><p>{{report.issues.length?'有 '+report.issues.length+' 项需要处理':'可用制作内容可供导出'}}</p><details v-if="report.issues.length"><summary>查看检查项</summary><p v-for="issue in report.issues">{{issue.entity}}：{{issue.message}}</p></details><div class="actions"><button :disabled="busy" @click="download('zip',true)">导出草稿ZIP</button><button :disabled="busy" @click="download('json',true)">导出草稿JSON</button><button :disabled="busy" @click="download('md',true)">导出草稿Markdown</button></div><button v-if="version===s.p.value.version&&!report.issues.length" :disabled="busy" @click="download('zip',false)">导出可用叙事包ZIP</button><small>AI来源与人工核对状态随包保留，无需重复确认。</small></template></section></template>
